const express = require('express');
const { chromium } = require('playwright');
const path = require('path');
const fs = require('fs');
const db = require('../db');

const app = express();
app.use(express.json());
const SESSIONS_DIR = path.resolve(__dirname, '../stored_sessions');

app.post('/api/browser-sessions/replay-snapshot', async (req, res) => {
  const { userSessionId, targetRoute } = req.body;

  // Validate that the session record belongs to the requesting user or their authorized organization
  const sessionRecord = await db('user_web_sessions')
    .where({ session_id: userSessionId, user_id: req.user.id })
    .first();
  if (!sessionRecord) {
    return res.status(404).json({ error: 'Saved browser session state not found' });
  }

  const storageStatePath = path.join(SESSIONS_DIR, `${userSessionId}.json`);
  if (!fs.existsSync(storageStatePath)) {
    return res.status(404).json({ error: 'Saved browser session state not found' });
  }

  // Launch Playwright restoring the validated user session storage state
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ storageState: storageStatePath });
  const page = await context.newPage();

  await page.goto(`https://app.saasplatform.com${targetRoute || '/dashboard'}`);
  const screenshotBuffer = await page.screenshot({ fullPage: false });

  await browser.close();
  res.setHeader('Content-Type', 'image/png');
  return res.send(screenshotBuffer);
});

module.exports = app;
